  await request(async (_url, init) => {
    assert.equal(init.method, 'POST');
    committed++;
    return { status: committed < 3 ? 503 : 200 };
  }, 'https://x.test/charge', { init: { method: 'POST', body: 'charge' }, baseDelayMs: 0 });
  console.log('POST side effects after two transient responses:', committed);
  let cancelled = 0, consumed = 0, calls = 0;
  await request(async () => ({
    status: ++calls < 3 ? 503 : 200,
    body: { cancel() { cancelled++; } },
    text() { consumed++; return Promise.resolve(''); }
